values
  ('10000000-0000-4000-8000-000000000001', 'towels', 'الفوط',
insert into public.products
  (id, slug, name_ar, category_id, description_ar, details_ar, care_ar, base_price, personalization_fee, images, sort, created_at)
values
  ('00000000-0000-4000-8000-000000000002', 'printed-kitchen-towel', 'فوطة مطبخ مطبوعة', '10000000-0000-4000-8000-000000000001', 'فوطة مطبخ قطنية برسمة وجملة مصرية خفيفة وشرايط على الطرفين. اطلبها زي ما هي، أو اكتب اسمك عليها، أو ارفع تصميمك.', 'خامة قطن مصري 100% عالي الامتصاص، مقاس 45 × 65 سم، طباعة رقمية ألوانها ثابتة مع الغسيل المتكرر.', 'تغسل في الغسالة بماء بارد أو دافئ حتى 40 درجة، تكوى على الظهر للحفاظ على الرسومات.', 90, 25, '[{"src":"/products/towel-black.jpg","alt":"فوطة مطبخ سودا عليها رسمة بنت بتغسل المواعين وجملة مصرية","position":"center 42%"},{"src":"/products/towel-cream.jpg","alt":"فوطة بيج عليها رسمة وجملة تعبان مش تعبان","position":"center 42%"}]'::jsonb, 1, '2026-03-01T10:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000011', 'taaban-mesh-taaban-towel', 'فوطة تعبان مش تعبان', '10000000-0000-4000-8000-000000000001', 'فوطة كوميدية خفيفة الظل برسمة الزوجين وكوباية الشاي وجملة تعبان مش تعبان هتعملي الغدا بردك.', 'قطن ناعم ممتاز مع شرايط ديكورية على الحواف، سريعة الجفاف وتتحمل الاستخدام اليومي.', 'غسيل آلي خفيف، تجنب استخدام المبيضات، وتكوى بحرارة متوسطة.', 95, 25, '[{"src":"/products/towel-cream.jpg","alt":"فوطة بيج عليها رسمة وجملة تعبان مش تعبان","position":"center 42%"},{"src":"/products/towel-black.jpg","alt":"فوطة مطبخ سودا عليها رسمة","position":"center 42%"}]'::jsonb, 2, '2026-03-01T10:05:00.000Z'),
  ('00000000-0000-4000-8000-000000000012', 'dishwashing-queen-towel', 'فوطة ملكة المواعين', '10000000-0000-4000-8000-000000000001', 'فوطة شياكة للمطبخ برسمة بنت المواعين ورغاوي الصابون وجملة مصرية أصيلة تضيف بهجة للحوض.', 'قطن مصري 100% كثيف وخفيف الوزن، نسيج مخصص لتجفيف الأطباق والكاسات بدون وبر.', 'غسيل غسالة بماء بارد، ونشر في الهواء الطلق.', 95, 25, '[{"src":"/products/towel-black.jpg","alt":"فوطة ملكة المواعين السوداء","position":"center 42%"},{"src":"/products/towel-cream.jpg","alt":"فوطة تعبان مش تعبان البيج","position":"center 42%"}]'::jsonb, 3, '2026-03-01T10:10:00.000Z'),
  ('00000000-0000-4000-8000-000000000013', 'morning-coffee-towel', 'فوطة قهوة الصباح', '10000000-0000-4000-8000-000000000001', 'فوطة مخصصة لركن القهوة والمشروبات الصباحية برسمة دافئة تحبب في بداية كل يوم.', 'ألياف قطنية عالية النعومة مع قدرة امتصاص فائقة للسوائل المنسكبة.', 'يغسل مع ألوان مشابهة، الكي على ظهر القماش.', 85, 25, '[{"src":"/products/towel-cream.jpg","alt":"فوطة قهوة الصباح برسمة دافئة","position":"center 42%"},{"src":"/products/towel-black.jpg","alt":"فوطة مطبخ أنيقة","position":"center 42%"}]'::jsonb, 4, '2026-03-01T10:15:00.000Z'),
  ('00000000-0000-4000-8000-000000000014', 'egyptian-cotton-towel', 'فوطة قطن مصري فاخر', '10000000-0000-4000-8000-000000000001', 'فوطة سفرة ومطبخ فخمة من أجود خيوط القطن المصري طويل التيلة مع تطريز وطباعة حصرية.', 'وزن 450 جرام لكل متر مربع، نعومة تدوم لسنوات ولا تتأثر بالغسيل الدوري.', 'غسيل عادي حتى 60 درجة مئوية، آمنة للاستخدام اليومي الشاق.', 110, 25, '[{"src":"/products/towel-black.jpg","alt":"فوطة قطن مصري فاخر سوداء","position":"center 42%"},{"src":"/products/towel-cream.jpg","alt":"فوطة قطن بيج طبيعي","position":"center 42%"}]'::jsonb, 5, '2026-03-01T10:20:00.000Z'),
  ('00000000-0000-4000-8000-000000000015', 'baking-day-towel', 'فوطة يوم الخبز والمعجنات', '10000000-0000-4000-8000-000000000001', 'فوطة واسعة مناسبة لتغطية العجين وتجفيف أدوات الحلويات، بنقوش لطيفة لأجواء الخبز البيتي.', 'مقاس عريض 50 × 70 سم، قطن مسامي يسمح للعجين بالتنفس دون أن يلتصق به.', 'غسيل بدون معطرات قوية للحفاظ على رائحة الخبز الزكية.', 90, 25, '[{"src":"/products/towel-cream.jpg","alt":"فوطة الخبز والمعجنات قطن كريمي","position":"center 42%"},{"src":"/products/towel-black.jpg","alt":"فوطة مطبخ خبازين","position":"center 42%"}]'::jsonb, 6, '2026-03-01T10:25:00.000Z'),
  ('00000000-0000-4000-8000-000000000016', 'chef-quote-towel', 'فوطة حِكَم المطبخ', '10000000-0000-4000-8000-000000000001', 'فوطة مطبوعة بعبارات طريفة ونصائح شيفات مشهورة، مثالية كهدية مبتكرة لست الكل.', 'قطن 100% بحواف معززة بالخياطة المزدوجة لمنع التنسيل.', 'غسيل آلي، تجفيف بالهواء، والكي على درجة حرارة قطن.', 85, 25, '[{"src":"/products/towel-black.jpg","alt":"فوطة حِكَم المطبخ الأنيقة","position":"center 42%"},{"src":"/products/towel-cream.jpg","alt":"فوطة اقتباسات الشيفات","position":"center 42%"}]'::jsonb, 7, '2026-03-01T10:30:00.000Z'),
  ('00000000-0000-4000-8000-000000000017', 'vintage-recipe-towel', 'فوطة وصفات زمان', '10000000-0000-4000-8000-000000000001', 'فوطة بتصميم مستوحى من كراسات وصفات الجدات والرسومات التراثية القديمة.', 'لون كريمي هادئ مع تفاصيل مطبوعة بألوان ثابتة غير قابلة للبهتان.', 'غسيل لطيف وكي بخار خفيف.', 100, 25, '[{"src":"/products/towel-cream.jpg","alt":"فوطة وصفات زمان الكلاسيكية","position":"center 42%"},{"src":"/products/towel-black.jpg","alt":"فوطة تراثية للمطبخ","position":"center 42%"}]'::jsonb, 8, '2026-03-01T10:35:00.000Z'),
  ('00000000-0000-4000-8000-000000000018', 'tea-time-towel', 'فوطة شاي العصرية', '10000000-0000-4000-8000-000000000001', 'فوطة أنيقة لتقديم صواني الشاي والبسكويت برسمة براد الشاي المصري الأصيل.', 'خفيفة ومثالية كفرش تحت الصواني ولتجفيف أدوات الشاي الحساسة.', 'تغسل باليد أو الغسالة بمسحوق خفيف.', 90, 25, '[{"src":"/products/towel-black.jpg","alt":"فوطة شاي العصرية باللون الأسود","position":"center 42%"},{"src":"/products/towel-cream.jpg","alt":"فوطة شاي العصرية البيج","position":"center 42%"}]'::jsonb, 9, '2026-03-01T10:40:00.000Z'),
  ('00000000-0000-4000-8000-000000000019', 'personalized-name-towel', 'فوطة مخصصة باسمك', '10000000-0000-4000-8000-000000000001', 'فوطة مطبخ فريدة تقدر تكتب عليها اسمك أو اسم عيلتك بالخط العربي المفضل لديك.', 'تخصيص كامل للنص مع اختيار نوع الخط ومكان الطباعة على القماش.', 'طباعة مقاومة لدرجات الحرارة العالية والغسيل المستمر.', 120, 0, '[{"src":"/products/towel-cream.jpg","alt":"فوطة مخصصة بالاسم باللون الكريمي","position":"center 42%"},{"src":"/products/towel-black.jpg","alt":"فوطة مخصصة بالاسم باللون الأسود","position":"center 42%"}]'::jsonb, 10, '2026-03-01T10:45:00.000Z'),
  ('00000000-0000-4000-8000-000000000001', 'chef-apron', 'مريلة مطبخ Chef', '10000000-0000-4000-8000-000000000002', 'مريلة مطبخ قماش بجيب قدّام وأربطة طويلة بتتربط على الوسط. اطلبها زي ما هي، أو اكتب اسمك عليها، أو ارفع تصميمك.', 'قماش كانفاس متين مقاوم للحرارة والبقع، حزام رقبة مريح قابل للتعديل وجيب أمامي مقسم للأدوات.', 'تغسل في الغسالة بماء بارد وتكوى من الخلف.', 120, 25, '[{"src":"/products/apron-chef.jpg","alt":"بنت لابسة مريلة بيج مطبوع عليها Chef Fatma","position":"center 25%"},{"src":"/products/apron-pink.jpg","alt":"بنت لابسة مريلة Chef وماسكة مريلة بينك","position":"center 22%"}]'::jsonb, 1, '2026-03-02T10:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000021', 'pink-classic-apron', 'مريلة وردي كلاسيك', '10000000-0000-4000-8000-000000000002', 'مريلة بلون وردي مبهج وتفاصيل أنيقة تعطي طاقة إيجابية ولمسة نعومة في المطبخ.', 'قماش تركي معالج ضد انكماش الغسيل مع رباط خصر عريض وثابت.', 'غسيل بدرجة حرارة لا تتعدى 40 درجة، تجنب المبيضات.', 130, 25, '[{"src":"/products/apron-pink.jpg","alt":"مريلة وردي كلاسيك مبهجة","position":"center 22%"},{"src":"/products/apron-chef.jpg","alt":"مريلة شيف بيج أنيقة","position":"center 25%"}]'::jsonb, 2, '2026-03-02T10:05:00.000Z'),
  ('00000000-0000-4000-8000-000000000022', 'linen-baker-apron', 'مريلة خباز كتان', '10000000-0000-4000-8000-000000000002', 'مريلة عملية من خامة الكتان الطبيعي خفيفة وباردة لعشاق الخبز وصناعة البيتزا والحلويات.', 'مزيج قطن وكتان مسامي يسمح بالتهوية مع حماية كاملة للملابس من الدقيق ورذاذ الزيت.', 'يفضل الكي وهي رطبة قليلاً للحصول على مظهر الكتان الانسيابي الفاخر.', 140, 25, '[{"src":"/products/apron-chef.jpg","alt":"مريلة خباز كتان طبيعي بيج","position":"center 25%"},{"src":"/products/apron-pink.jpg","alt":"مريلة كتان وردي","position":"center 22%"}]'::jsonb, 3, '2026-03-02T10:10:00.000Z'),
  ('00000000-0000-4000-8000-000000000023', 'master-chef-apron', 'مريلة الشيف المحترف', '10000000-0000-4000-8000-000000000002', 'تصميم مخصص للمطابخ النشطة مع حمالات ظهر متقاطعة X-back تمنع أي إجهاد للرقبة.', 'كانفاس ثقيل 12 أونصة مع حلقات نحاسية متينة وأربطة قطنية مصفحة.', 'تغسل في الغسالة ببرنامج الأقمشة الثقيلة، وتكوى على حرارة عالية.', 150, 25, '[{"src":"/products/apron-pink.jpg","alt":"مريلة الشيف المحترف بإطلالة عصرية","position":"center 22%"},{"src":"/products/apron-chef.jpg","alt":"مريلة الشيف بيج متينة","position":"center 25%"}]'::jsonb, 4, '2026-03-02T10:15:00.000Z'),
  ('00000000-0000-4000-8000-000000000024', 'pocket-canvas-apron', 'مريلة بجيوب متعددة', '10000000-0000-4000-8000-000000000002', 'مريلة مزودة بـ 3 جيوب عملية واسعة لحمل الفوطة والموبايل وملاعق التذوق وأقلام الملاحظات.', 'خياطة ثلاثية مدعومة في نقاط الضغط لتتحمل الأحمال اليومية والشد.', 'غسيل آلي آمن ومقاومة لتغير المقاس والانكماش.', 135, 25, '[{"src":"/products/apron-chef.jpg","alt":"مريلة كانفاس بجيوب عملية","position":"center 25%"},{"src":"/products/apron-pink.jpg","alt":"مريلة بجيوب متعددة وردية","position":"center 22%"}]'::jsonb, 5, '2026-03-02T10:20:00.000Z'),
  ('00000000-0000-4000-8000-000000000025', 'vintage-kitchen-apron', 'مريلة مطبخ فينتدج', '10000000-0000-4000-8000-000000000002', 'مريلة بلمسة نوستالجيا تجمع بين بساطة الماضي وجودة الخامات العصرية الأنيقة.', 'قماش ناعم بألوان دافئة وتطريز جانبي رقيق يضفي وقاراً وأناقة خاصة.', 'غسيل يدوي أو آلي دورة خفيفة، والتجفيف على شماعة.', 125, 25, '[{"src":"/products/apron-pink.jpg","alt":"مريلة فينتدج وردية هادئة","position":"center 22%"},{"src":"/products/apron-chef.jpg","alt":"مريلة كلاسيك كافيه","position":"center 25%"}]'::jsonb, 6, '2026-03-02T10:25:00.000Z'),
  ('00000000-0000-4000-8000-000000000026', 'personalized-chef-apron', 'مريلة مخصصة باسم الشيف', '10000000-0000-4000-8000-000000000002', 'اكتب اسمك أو لقبك المفضل مثل Chef Sarah أو مطبخ أمي بالخط العربي الفاخر.', 'طباعة فينيل حراري مصفح عالية الدقة لا تتأثر بحرارة الطهي أو البخار.', 'تغسل مقلوبة ولا يوضع المكواة مباشرة على حروف الطباعة.', 160, 0, '[{"src":"/products/apron-chef.jpg","alt":"مريلة مطبوعة باسم الشيف مخصصة","position":"center 25%"},{"src":"/products/apron-pink.jpg","alt":"مريلة مخصصة باسمك بينك","position":"center 22%"}]'::jsonb, 7, '2026-03-02T10:30:00.000Z'),
  ('00000000-0000-4000-8000-000000000027', 'kids-kitchen-apron', 'مريلة الشيف الصغير', '10000000-0000-4000-8000-000000000002', 'مريلة للأطفال تشجعهم على المشاركة في إعداد الكوكيز والمخبوزات اللذيذة بأمان.', 'مقاس مناسب للأعمار من 4 إلى 10 سنوات، خامات آمنة وغير مسببة للحساسية.', 'غسيل متكرر سريع وسهلة إزالة بقع الشوكولاتة والعصير.', 95, 20, '[{"src":"/products/apron-pink.jpg","alt":"مريلة الشيف الصغير الوردية للأطفال","position":"center 22%"},{"src":"/products/apron-chef.jpg","alt":"مريلة أطفال بيج","position":"center 25%"}]'::jsonb, 8, '2026-03-02T10:35:00.000Z'),
  ('00000000-0000-4000-8000-000000000028', 'stripes-apron', 'مريلة خطوط بيكري', '10000000-0000-4000-8000-000000000002', 'مريلة بخطوط طولية كلاسيكية مستوحاة من مخابز ومطاعم باريس الكلاسيكية الراقية.', 'نسيج قطني منسوج الخيوط مسبقاً (Yarn-dyed) ليحافظ على بريق الخطوط مدى الحياة.', 'غسيل عادي حتى 40 درجة مئوية، ومقاومة للتجاعيد.', 115, 25, '[{"src":"/products/apron-chef.jpg","alt":"مريلة خطوط كلاسيكية بيج","position":"center 25%"},{"src":"/products/apron-pink.jpg","alt":"مريلة خطوط أنيقة","position":"center 22%"}]'::jsonb, 9, '2026-03-02T10:40:00.000Z'),
  ('00000000-0000-4000-8000-000000000029', 'artist-studio-apron', 'مريلة ورشة واستوديو', '10000000-0000-4000-8000-000000000002', 'مريلة متعددة الاستخدامات للطبخ، الفخار، الرسم، وتنسيق الزهور بكل راحة وحرية حركة.', 'فتحة أمامية في المنتصف تسهل الجلوس والحركة أثناء العمل في الاستوديو.', 'تتحمل درجات الغسيل العالية وتزداد جمالاً مع كل غسلة.', 145, 25, '[{"src":"/products/apron-pink.jpg","alt":"مريلة استوديو وورشة فنية","position":"center 22%"},{"src":"/products/apron-chef.jpg","alt":"مريلة ورشة قماش طبيعي","position":"center 25%"}]'::jsonb, 10, '2026-03-02T10:45:00.000Z'),
  ('00000000-0000-4000-8000-000000000003', 'polka-dot-bag', 'شنطة Polka Dot صفرا', '10000000-0000-4000-8000-000000000003', 'شنطة قماش صفرا بنقط بني، واسعة وخفيفة بيد طويلة على الكتف. اطلبها زي ما هي، أو اكتب اسمك عليها، أو ارفع تصميمك.', 'قماش كانفاس قطني 100% متين، مقاس 40 × 42 سم مع يد مريحة بطول 65 سم لحمل الكتف بسهولة.', 'غسيل يدوي أو آلي خفيف بماء بارد، وتكوى على الظهر للحفاظ على الألوان.', 130, 25, '[{"src":"/products/bag-hanging.jpg","alt":"شنطة قماش صفرا بنقط بني معلقة على شماعة","position":"center 55%"},{"src":"/products/bag-polka.jpg","alt":"بنت شايلة شنطة صفرا بنقط بني","position":"center 30%"}]'::jsonb, 1, '2026-03-03T10:00:00.000Z'),
  ('00000000-0000-4000-8000-000000000031', 'canvas-tote-bag', 'شنطة توت باج قماشية', '10000000-0000-4000-8000-000000000003', 'شنطة توت باج كلاسيكية بلون أصفر صيفي مشرق، رفيقتك المثالية في المشاوير والتسوق اليومي.', 'خامة كانفاس ثقيلة تتحمل حتى وزن 10 كجم مع خياطة مدبلة عند مقابض الكتف.', 'تغسل مقلوبة في ماء بارد وتترك لتجف في الهواء الطلق.', 120, 25, '[{"src":"/products/bag-polka.jpg","alt":"شنطة توت باج قماشية صفراء","position":"center 30%"},{"src":"/products/bag-hanging.jpg","alt":"شنطة توت باج معلقة","position":"center 55%"}]'::jsonb, 2, '2026-03-03T10:05:00.000Z'),
  ('00000000-0000-4000-8000-000000000032', 'hanging-kitchen-bag', 'شنطة تسوق قماش عملية', '10000000-0000-4000-8000-000000000003', 'شنطة واسعة وسهلة الطي للاحتفاظ بها في الشنطة أو تعليقها في المطبخ كديكور واستخدام سريع.', 'قماش قطني ناعم صديق للبيئة وبديل صحي ومستدام للأكياس البلاستيكية.', 'قابلة للغسيل وإعادة الاستخدام لمئات المرات دون فقدان ألوانها.', 125, 25, '[{"src":"/products/bag-hanging.jpg","alt":"شنطة تسوق قماش عملية معلقة","position":"center 55%"},{"src":"/products/bag-close.jpg","alt":"تفاصيل نسيج شنطة القماش","position":"center 50%"}]'::jsonb, 3, '2026-03-03T10:10:00.000Z'),
  ('00000000-0000-4000-8000-000000000033', 'university-canvas-bag', 'شنطة جامعة واسعة', '10000000-0000-4000-8000-000000000003', 'حجم كبير يتسع للابتوب حتى 15 بوصة والدفاتر والكتب مع جيب داخلي منظم للأغراض الصغيرة.', 'قاعدة عريضة ومبطنة لتمنح الشنطة قواماً ثابتاً أثناء وضعها على المقاعد والمكاتب.', 'تنظيف موضعي للبقع أو غسيل غسالة خفيف.', 140, 25, '[{"src":"/products/bag-polka.jpg","alt":"شنطة جامعة واسعة للكتف","position":"center 30%"},{"src":"/products/bag-hanging.jpg","alt":"شنطة قماش للمكتب والجامعة","position":"center 55%"}]'::jsonb, 4, '2026-03-03T10:15:00.000Z'),
  ('00000000-0000-4000-8000-000000000034', 'market-shopping-tote', 'شنطة تسوق للماركت', '10000000-0000-4000-8000-000000000003', 'متينة جداً ومريحة في مسك اليد لحمل الخضار والفاكهة ومنتجات البقالة بأناقة واسترخاء.', 'مقابض مزدوجة محاكة بغرز أمان ثلاثية لتمنع قطع الحزام حتى مع الوزن الثقيل.', 'غسيل آلي سريع وتجفيف سهل وسريع.', 115, 25, '[{"src":"/products/bag-hanging.jpg","alt":"شنطة تسوق متينة للماركت","position":"center 55%"},{"src":"/products/bag-polka.jpg","alt":"شنطة تسوق كتف","position":"center 30%"}]'::jsonb, 5, '2026-03-03T10:20:00.000Z'),
  ('00000000-0000-4000-8000-000000000035', 'daily-outing-bag', 'شنطة خروجة يومية', '10000000-0000-4000-8000-000000000003', 'شنطة خفيفة وعصرية تناسب طلعات الكافيهات، النادي، والمشاوير السريعة بألوان تلفت النظر.', 'قماش ناعم الملمس بلون أصفر خردلي مميز ونقاط دائرية أنيقة.', 'تكوى على الظهر لحفظ نعومة السطح.', 135, 25, '[{"src":"/products/bag-polka.jpg","alt":"شنطة خروجة يومية عصرية","position":"center 30%"},{"src":"/products/bag-close.jpg","alt":"تفاصيل النقاط على قماش الشنطة","position":"center 50%"}]'::jsonb, 6, '2026-03-03T10:25:00.000Z'),
  ('00000000-0000-4000-8000-000000000036', 'personalized-name-bag', 'شنطة باسمك وتصميمك', '10000000-0000-4000-8000-000000000003', 'شنطة فريدة تحمل اسمك أو عبارتك المفضلة مطبوعة بدقة عالية ومقاومة للغسيل والاستخدام.', 'إمكانية اختيار الخط العربي أو الإنجليزي وإضافة رسومات شخصية.', 'غسيل مقلوب بالماء البارد دون استخدام مبيضات.', 160, 0, '[{"src":"/products/bag-hanging.jpg","alt":"شنطة مخصصة بالاسم والعبارات","position":"center 55%"},{"src":"/products/bag-polka.jpg","alt":"شنطة مخصصة بالاسم للموديل","position":"center 30%"}]'::jsonb, 7, '2026-03-03T10:30:00.000Z'),
  ('00000000-0000-4000-8000-000000000037', 'beach-summer-tote', 'شنطة مصيف وشاطئ', '10000000-0000-4000-8000-000000000003', 'شنطة بحجم كبير تسع الفوط والنظارة الشمسية والكريمات مع سعة رحبة وأجواء صيفية مبهرة.', 'قماش قطني سريع النفض من الرمال وخفيف الحمل على الكتف حتى أثناء الامتلاء.', 'غسيل بماء عذب بعد رحلات الشاطئ للحفاظ على نضارة الألوان.', 150, 25, '[{"src":"/products/bag-polka.jpg","alt":"شنطة صيف وشاطئ صفراء واسعة","position":"center 30%"},{"src":"/products/bag-hanging.jpg","alt":"شنطة مصيف معلقة في الشاليه","position":"center 55%"}]'::jsonb, 8, '2026-03-03T10:35:00.000Z'),
  ('00000000-0000-4000-8000-000000000038', 'minimal-cotton-tote', 'شنطة قطن مينيمال', '10000000-0000-4000-8000-000000000003', 'تصميم بسيط هادئ يركز على جودة القطن الطبيعي وخفة الوزن لتناسب كل الأذواق والإطلالات.', 'خالية من الإضافات المعقدة، سهلة الغسيل وسريعة الجفاف والطي.', 'غسيل آلي عادي بدون أي شروط خاصة.', 110, 25, '[{"src":"/products/bag-hanging.jpg","alt":"شنطة قطن مينيمال بسيطة وعملية","position":"center 55%"},{"src":"/products/bag-close.jpg","alt":"قماش الشنطة المينيمال عن قرب","position":"center 50%"}]'::jsonb, 9, '2026-03-03T10:40:00.000Z'),
  ('00000000-0000-4000-8000-000000000039', 'book-lover-tote', 'شنطة عشاق القراءة', '10000000-0000-4000-8000-000000000003', 'شنطة مصممة خصيصاً لحمل الروايات والكتب ومستلزمات الدراسة دون أن ترهق الكتف أو تنحني الحواف.', 'جوانب معززة تحمي أركان الكتب والروايات من التلف أثناء التنقل.', 'غسيل مقلوب بالماء البارد والكي بحرارة منخفضة.', 125, 25, '[{"src":"/products/bag-polka.jpg","alt":"شنطة عشاق القراءة والكتب","position":"center 30%"},{"src":"/products/bag-hanging.jpg","alt":"شنطة قماشية للكتب والمذكرات","position":"center 55%"}]'::jsonb, 10, '2026-03-03T10:45:00.000Z')
